path = 'axum/src/extract/matched_path.rs'
replace(path, '/// # Matched path in nested routers', '''/// `MatchedPath` is not available in fallback handlers, since no route was matched.
///
/// # Matched path in nested routers''')
replace(path, '''    #[crate::test]
    async fn extracting_on_handler_in_nested_router() {''', '''    #[crate::test]
    async fn cannot_extract_matched_path_in_fallback() {
        async fn fallback(path: Option<MatchedPath>) {
            assert!(path.is_none());
        }

        let app = Router::new()
            .nest("/nested", Router::new().fallback(fallback))
            .fallback(fallback);

        let client = TestClient::new(app);

        for path in ["/", "/foo", "/nested", "/nested/", "/nested/foo"] {
            let res = client.get(path).send().await;
            assert_eq!(res.status(), StatusCode::OK);
        }
    }

    #[crate::test]
    async fn extracting_on_handler_in_fallback_router() {
        async fn handler(path: MatchedPath) -> String {
            path.as_str().to_owned()
        }

        let fallback = Router::new().route("/:a", get(handler)).nest_service(
            "/nested",
            Router::new().route("/:b", get(handler)),
        );
        let app = Router::new().fallback_service(fallback);

        let client = TestClient::new(app);

        for (path, expected) in [("/foo", "/:a"), ("/nested/foo", "/nested/:b")] {
            let res = client.get(path).send().await;
            assert_eq!(res.status(), StatusCode::OK);
            assert_eq!(res.text().await, expected);
        }
    }

    #[crate::test]
    async fn extracting_on_handler_in_nested_router() {''')
replace('axum/CHANGELOG.md', '- None.', '- **fixed:** Prevent fallback routes from setting `MatchedPath`, fixing a panic\n  when using a nested `ServeDir` router as a fallback service.')
